macro_rules! deps {
    () => {
        Range!();
        Solution!();
        Diff!();
    };
}

macro_rules! cleanup_merge {
    () => {
        deps!();
        fn cleanup_merge (solution : & mut Solution) { let diffs = & mut solution . diffs ; while ! diffs . is_empty () { diffs . push (Diff :: Equal (solution . text1 . substring (solution . text1 . len ..) , solution . text2 . substring (solution . text2 . len ..) ,)) ; let mut pointer = 0 ; let mut count_delete = 0 ; let mut count_insert = 0 ; let mut text_delete = Range :: empty () ; let mut text_insert = Range :: empty () ; while let Some (& this_diff) = diffs . get (pointer) { match this_diff { Diff :: Insert (text) => { count_insert += 1 ; if text_insert . is_empty () { text_insert = text ; } else { text_insert . len += text . len ; } } Diff :: Delete (text) => { count_delete += 1 ; if text_delete . is_empty () { text_delete = text ; } else { text_delete . len += text . len ; } } Diff :: Equal (text , _) => { let count_both = count_delete + count_insert ; if count_both > 1 { let both_types = count_delete != 0 && count_insert != 0 ; diffs . drain (pointer - count_both .. pointer) ; pointer -= count_both ; if both_types { let common_length = common_prefix (text_insert , text_delete) ; if common_length != 0 { if pointer > 0 { match & mut diffs [pointer - 1] { Diff :: Equal (this_diff1 , this_diff2) => { this_diff1 . len += common_length ; this_diff2 . len += common_length ; } _ => unreachable ! ("previous diff should have been an equality") , } } else { diffs . insert (pointer , Diff :: Equal (text_delete . substring (.. common_length) , text_insert . substring (.. common_length) ,) ,) ; pointer += 1 ; } text_insert = text_insert . substring (common_length ..) ; text_delete = text_delete . substring (common_length ..) ; } let common_length = common_suffix (text_insert , text_delete) ; if common_length != 0 { diffs [pointer] . grow_left (common_length) ; text_insert . len -= common_length ; text_delete . len -= common_length ; } } if ! text_delete . is_empty () { diffs . insert (pointer , Diff :: Delete (text_delete)) ; pointer += 1 ; } if ! text_insert . is_empty () { diffs . insert (pointer , Diff :: Insert (text_insert)) ; pointer += 1 ; } } else if pointer > 0 { if let Some (Diff :: Equal (prev_equal1 , prev_equal2)) = diffs . get_mut (pointer - 1) { prev_equal1 . len += text . len ; prev_equal2 . len += text . len ; diffs . remove (pointer) ; pointer -= 1 ; } } count_insert = 0 ; count_delete = 0 ; text_delete = Range :: empty () ; text_insert = Range :: empty () ; } } pointer += 1 ; } if diffs . last () . unwrap () . text () . is_empty () { diffs . pop () ; } let mut changes = false ; let mut pointer = 1 ; while let Some (& next_diff) = diffs . get (pointer + 1) { let prev_diff = diffs [pointer - 1] ; let this_diff = diffs [pointer] ; if let (Diff :: Equal (prev_diff , _) , Diff :: Equal (next_diff , _)) = (prev_diff , next_diff) { if this_diff . text () . ends_with (prev_diff) { diffs [pointer] . shift_left (prev_diff . len) ; diffs [pointer + 1] . grow_left (prev_diff . len) ; diffs . remove (pointer - 1) ; changes = true ; } else if this_diff . text () . starts_with (next_diff) { diffs [pointer - 1] . grow_right (next_diff . len) ; diffs [pointer] . shift_right (next_diff . len) ; diffs . remove (pointer + 1) ; changes = true ; } } pointer += 1 ; } if ! changes { return ; } } }
    };
}

cleanup_merge!();